SELECT * FROM booking
WHERE user_id = #{userId}
ORDER BY date DESC, start_time DESC

SELECT * FROM booking
WHERE user_id = #{userId}

    AND date >= #{startDate}


    AND date <= #{endDate}

ORDER BY date DESC, start_time DESC

SELECT * FROM booking
WHERE room_id = #{roomId} AND date = #{date}
ORDER BY start_time

SELECT COUNT(*) FROM booking
WHERE room_id = #{roomId}
AND date = #{date}
AND status != 3

    AND id != #{excludeBookingId}

AND (
    (start_time < #{endTime} AND end_time > #{startTime})
)

mapper.update:
UPDATE booking
SET room_id = #{roomId}, user_id = #{userId}, date = #{date},
    start_time = #{startTime}, end_time = #{endTime}, subject = #{subject},
    attendee_count = #{attendeeCount}, remark = #{remark}, status = #{status}
WHERE id = #{id}
